mapper.select:
/* Attd03Mapper.selectLeaves */ SELECT A.CMPNY_CD AS cmpnyCd , A.LEAVE_CD AS leaveCd , A.LEAVE_NO AS leaveNo , A.LEAVE_NM AS leaveNm , A.LEAVE_TYPE AS leaveType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.LEAVE_TYPE, 'SYS021') AS leaveTypeNm , A.GRANT_TYPE AS grantType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.GRANT_TYPE, 'SYS022') AS grantTypeNm , A.PAID_TYPE AS paidType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.PAID_TYPE, 'SYS023') AS paidTypeNm , A.LEAVE_NATURE_TYPE AS leaveNatureType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.LEAVE_NATURE_TYPE, 'SYS024') AS leaveNatureTypeNm , A.LEAVE_DAYS AS leaveDays , A.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.USE_UNIT_TYPE, 'SYS025') AS useUnitTypeNm , A.AVAIL_TERM_TYPE AS availTermType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.AVAIL_TERM_TYPE, 'SYS026') AS availTermTypeNm , A.AVAIL_PERIOD AS availPeriod , A.USE_YN AS useYn , A.LEAVE_DESC AS leaveDesc , A.GRANT_BASE_TYPE AS grantBaseType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.GRANT_BASE_TYPE, 'SYS027') AS grantBaseTypeNm , A.GRANT_OFFSET_MONTH AS grantOffsetMonth , A.GRANT_ASSIGN_MMDD AS grantAssignMmdd
, A.APRV_USE_YN AS aprvUseYn , A.EVIDENCE_YN AS evidenceYn , A.EVIDENCE_GUIDE_MSG AS evidenceGuideMsg
/* prafta-044-FU / prafta-com-016-B: 관리자 부여 사용가능기간 편집 복원용 원본 컬럼 직접 노출 (record LeaveTypeResult 끝 2필드와 위치 1:1 정합 — 끝에 추가) */ , A.ADMIN_AVAIL_TERM_TYPE AS adminAvailTermType , A.ADMIN_AVAIL_MONTHS AS adminAvailMonths FROM ( SELECT A.CMPNY_CD , A.LEAVE_CD , A.LEAVE_NO , A.LEAVE_NM , A.LEAVE_TYPE , A.GRANT_TYPE , A.PAID_TYPE , A.LEAVE_NATURE_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN A.MAX_APLY_DAYS ELSE NULL END LEAVE_DAYS , A.USE_UNIT_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN A.AVAIL_TERM_TYPE WHEN A.LEAVE_TYPE = '02' THEN A.ADMIN_AVAIL_TERM_TYPE END AVAIL_TERM_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN CONCAT(A.AVAIL_FROM_DT, '~', A.AVAIL_TO_DT) WHEN A.LEAVE_TYPE = '02' /* prafta-com-016-B: 관리자 부여 '03' 기간설정 = 부여일로부터 N개월 표시 */ THEN CONCAT(A.ADMIN_AVAIL_MONTHS, '개월') END AVAIL_PERIOD , A.USE_YN , A.LEAVE_DESC
, A.GRANT_BASE_TYPE , A.GRANT_OFFSET_MONTH , A.GRANT_ASSIGN_MMDD
, A.APRV_USE_YN , A.EVIDENCE_YN , A.EVIDENCE_GUIDE_MSG
/* prafta-044-FU / prafta-com-016-B: 편집 복원용 관리자 부여 사용가능기간 원본 컬럼 (목록 표시용 CASE/CONCAT 과 병존) */ , A.ADMIN_AVAIL_TERM_TYPE , A.ADMIN_AVAIL_MONTHS FROM TB_LEAVE_TYPE_MGMT A WHERE A.CMPNY_CD = #{gvCmpnyCd}
AND A.LEAVE_NO = #{leaveNo}
AND A.LEAVE_NM LIKE CONCAT('%', #{leaveNm}, '%')
AND A.LEAVE_TYPE = #{leaveType}
AND A.USE_YN = #{useYn}
) A

/* Attd03Mapper.selectLeaveNoDupChkResult */
SELECT
	A.CMPNY_CD 		AS cmpnyCd
	, A.LEAVE_CD	AS leaveCd
	, A.LEAVE_NO	AS leaveNo
	, A.LEAVE_NM	AS leaveNm
FROM TB_LEAVE_TYPE_MGMT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.LEAVE_NO = #{leaveNo}


  AND A.LEAVE_CD != #{leaveCd}

LIMIT 1

/* Attd03Mapper.selectSystemYn — PRAFTA-018 §8.5.5 시스템 시드 가드 */
SELECT A.SYSTEM_YN
  FROM TB_LEAVE_TYPE_MGMT A
 WHERE A.CMPNY_CD = #{gvCmpnyCd}
   AND A.LEAVE_CD = #{leaveCd}
 LIMIT 1
